//! Generated Serde models for Wisp's current live JSONL-RPC protocol.
//!
//! Python models and the committed JSON Schemas are the semantic source of
//! truth. The modules below are generated by `typify` at compile time and must
//! not be replaced with handwritten wire structs.

#![forbid(unsafe_code)]

use serde::de::DeserializeOwned;
use serde_json::Value;
use std::fmt;

#[derive(Debug)]
pub struct ProtocolDecodeError(String);

impl fmt::Display for ProtocolDecodeError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(&self.0)
    }
}

impl std::error::Error for ProtocolDecodeError {}

fn deserialize_known<T>(schema: &str, value: Value) -> Result<T, ProtocolDecodeError>
where
    T: DeserializeOwned,
{
    let discriminator = value
        .get("type")
        .and_then(Value::as_str)
        .ok_or_else(|| ProtocolDecodeError("RPC value has no string discriminator".into()))?;
    let schema: Value = serde_json::from_str(schema)
        .map_err(|error| ProtocolDecodeError(format!("invalid embedded schema: {error}")))?;
    let known = schema["discriminator"]["mapping"]
        .as_object()
        .is_some_and(|mapping| mapping.contains_key(discriminator));
    if !known {
        return Err(ProtocolDecodeError(format!(
            "unknown RPC discriminator: {discriminator}"
        )));
    }
    serde_json::from_value(value)
        .map_err(|error| ProtocolDecodeError(format!("invalid RPC value: {error}")))
}

pub mod handshake_request {
    typify::import_types!(schema = "../../schemas/live-rpc/v2/client-handshake.schema.json");
}

pub mod handshake_response {
    typify::import_types!(schema = "../../schemas/live-rpc/v2/server-handshake.schema.json");
}

pub mod commands {
    typify::import_types!(schema = "../../schemas/live-rpc/v2/rust-commands.schema.json");

    pub fn deserialize(
        value: serde_json::Value,
    ) -> Result<WispTypedClientRpcCommands, super::ProtocolDecodeError> {
        super::deserialize_known(
            include_str!("../../../schemas/live-rpc/v2/commands.schema.json"),
            value,
        )
    }
}

pub mod events {
    typify::import_types!(schema = "../../schemas/live-rpc/v2/rust-events.schema.json");

    pub fn deserialize(
        value: serde_json::Value,
    ) -> Result<WispCurrentLiveEventOutput, super::ProtocolDecodeError> {
        super::deserialize_known(
            include_str!("../../../schemas/live-rpc/v2/events.schema.json"),
            value,
        )
    }
}
